import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { SensorService, SensorData, DashboardInsights } from '../../Services/sensor.service';
import { AuthService } from '../../Services/auth.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit {
  stats: DashboardInsights | null = null;
  weatherData: any = null;
  sensorHistory: SensorData[] = [];

  // Filters
  filterType: string = 'All';
  filterSensorId: string = '';

  // Time Range Logic
  selectedRange: string = '24h'; // Default to 24 hours
  customStart: string = '';
  customEnd: string = '';

  isLoading: boolean = false;

  constructor(
    private sensorService: SensorService,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.loadStats();
    this.applyFilters(); // Load history with default 24h
  }

  loadStats(): void {
    this.sensorService.getStats().subscribe({
      next: (data) => {
        this.stats = data;
        if (data.latestWeather && data.latestWeather.value) {
          try {
            this.weatherData = JSON.parse(data.latestWeather.value);
          } catch {
            this.weatherData = null;
          }
        }
      },
      error: (err) => console.error(err)
    });
  }

  applyFilters(): void {
    this.isLoading = true;

    // Calculate Dates based on selection
    const now = new Date();
    let fromDate: Date = new Date();
    let toDate: Date = new Date();

    switch (this.selectedRange) {
      case '1h':
        fromDate.setHours(now.getHours() - 1);
        break;
      case '24h':
        fromDate.setHours(now.getHours() - 24);
        break;
      case '30d':
        fromDate.setDate(now.getDate() - 30);
        break;
      case 'custom':
        if (this.customStart) fromDate = new Date(this.customStart);
        if (this.customEnd) toDate = new Date(this.customEnd);
        break;
    }

    // Convert to ISO string for API (Remove milliseconds to match C# format if needed)
    const fromStr = this.toLocalIsoString(fromDate);
    const toStr = this.toLocalIsoString(toDate);

    this.sensorService.getHistory(
      this.filterType, 
      this.filterSensorId, 
      fromStr, 
      toStr
    ).subscribe({
      next: (data) => {
        this.sensorHistory = data.map(item => {
          if (item.value && item.value.trim().startsWith('{')) {
            try { return { ...item, parsedValue: JSON.parse(item.value) }; }
            catch { return { ...item, parsedValue: item.value }; }
          }
          return { ...item, parsedValue: item.value };
        });
        this.isLoading = false;
      },
      error: () => this.isLoading = false
    });
  }

  // Helper to get local time ISO string (instead of UTC) which matches your DB better
  toLocalIsoString(date: Date): string {
    const tzOffset = date.getTimezoneOffset() * 60000;
    const localISOTime = (new Date(date.getTime() - tzOffset)).toISOString().slice(0, -1);
    return localISOTime; // Format: YYYY-MM-DDTHH:mm:ss.sss
  }

  logout(): void {
    this.authService.logout();
    this.router.navigate(['/login']);
  }

  getPollutionClass(status: string): string {
    if (status === 'Good') return 'card-good';
    if (status === 'Moderate') return 'card-warning';
    return 'card-danger';
  }

  getTrafficClass(status: string): string {
    if (status === 'Clear') return 'card-good';
    if (status === 'Moderate') return 'card-warning';
    return 'card-danger';
  }
}
